CREATE OR REPLACE FUNCTION public.validate_request_booking() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.kind = 'Booking' AND (NEW.visit_date IS NULL OR NEW.visit_slot IS NULL) THEN RAISE EXCEPTION 'invalid slot: bookings require a date and time'; END IF; IF NEW.kind = 'Enquiry' THEN NEW.visit_date := NULL; NEW.visit_slot := NULL; END IF; RETURN NEW; END; $$; CREATE TRIGGER validate_request_booking BEFORE INSERT ON public.requests FOR EACH ROW EXECUTE FUNCTION public.validate_request_booking(); GRANT SELECT ON public.booking_settings, public.price_settings TO anon, authenticated; GRANT SELECT, UPDATE ON public.booking_settings, public.price_settings TO authenticated; GRANT SELECT, UPDATE, DELETE ON public.requests TO authenticated; GRANT ALL ON public.booking_settings, public.price_settings, public.requests TO service_role; GRANT EXECUTE ON FUNCTION public.get_booked_slots(date) TO anon, authenticated; GRANT EXECUTE ON FUNCTION public.submit_request(text,text,text,text,text,text,date,text,text) TO anon, authenticated;